import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
// @ts-ignore - validateMessage exists but will be extended
import {validateMessage} from './validation.js';
// @ts-ignore - createMessageHandler exists but its signature will change
import {createMessageHandler} from './messageHandler.js';

describe('Conversation List Acceptance', () => {
  describe('Protocol validation', () => {
    it('accepts list_conversations with optional limit and before', () => {
      // @ts-ignore
      expect(validateMessage({type: 'list_conversations'})).toMatchObject({
        valid: true,
        data: {type: 'list_conversations'},
      });

      // @ts-ignore
      expect(validateMessage({type: 'list_conversations', limit: 10})).toMatchObject({
        valid: true,
        data: {type: 'list_conversations', limit: 10},
      });

      const cursor = {updatedAt: '2026-11-08T12:00:00.000Z', sessionId: 's1'};
      // @ts-ignore
      expect(validateMessage({type: 'list_conversations', before: cursor})).toMatchObject({
        valid: true,
        data: {type: 'list_conversations', before: cursor},
      });
    });

    it('rejects invalid limit values', () => {
      const invalid = [0, 201, 1.5, '10', -1];
      for (const limit of invalid) {
        // @ts-ignore
        const result = validateMessage({type: 'list_conversations', limit});
        expect(result.valid).toBe(false);
        expect(result.error).toMatch(/limit/);
      }
    });

    it('rejects invalid before values', () => {
      const invalid = [
        'not a date',
        {updatedAt: 'not a date', sessionId: 's1'},
        {updatedAt: '2026-11-08T12:00:00.000Z'}, // missing sessionId
        {sessionId: 's1'}, // missing updatedAt
      ];
      for (const before of invalid) {
        // @ts-ignore
        const result = validateMessage({type: 'list_conversations', before});
        expect(result.valid).toBe(false);
        expect(result.error).toMatch(/before/);
      }
    });
  });

  describe('Successful list delivery', () => {
    it('returns conversation_list when history is enabled', async () => {
      const summaries = [
        {
          sessionId: 's2',
          createdAt: new Date('2026-11-08T11:00:00Z'),
          updatedAt: new Date('2026-11-08T11:30:00Z'),
          entryCount: 5,
        },
        {
          sessionId: 's1',
          createdAt: new Date('2026-11-08T10:00:00Z'),
          updatedAt: new Date('2026-11-08T10:30:00Z'),
          entryCount: 2,
        },
      ];

      const store = {
        listFor: jest.fn().mockResolvedValue(summaries),
      };

      const sent: any[] = [];
      const ws = {
        send: (raw: string) => sent.push(JSON.parse(raw)),
        userId: 'u1',
        readyState: 1, // WebSocket.OPEN
      };

      const orchestrator = {};
      const historyOptions = {enabled: true};
      // @ts-ignore
      const handle = createMessageHandler(orchestrator, store, {history: historyOptions});
      const session = {sessionId: 's3', userId: 'u1', entries: []};

      // @ts-ignore
      await handle(ws, session, {type: 'list_conversations'});

      expect(store.listFor).toHaveBeenCalledWith('u1', {limit: undefined, before: undefined});
      expect(sent).toEqual([
        {
          type: 'conversation_list',
          conversations: [
            {
              sessionId: 's2',
              createdAt: '2026-11-08T11:00:00.000Z',
              updatedAt: '2026-11-08T11:30:00.000Z',
              entryCount: 5,
            },
            {
              sessionId: 's1',
              createdAt: '2026-11-08T10:00:00.000Z',
              updatedAt: '2026-11-08T10:30:00.000Z',
              entryCount: 2,
            },
          ],
        },
      ]);
    });
  });

  describe('Feature opt-in', () => {
    it('answers with UNSUPPORTED error when history is disabled', async () => {
      const store = {listFor: jest.fn()};
      const sent: any[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw)), readyState: 1};

      // @ts-ignore
      const handle = createMessageHandler({}, store, {history: {enabled: false}});
      // @ts-ignore
      await handle(ws, {sessionId: 's1'}, {type: 'list_conversations'});

      expect(sent).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
      expect(store.listFor).not.toHaveBeenCalled();
    });
  });

  describe('Security: User Isolation', () => {
    it('always uses ws.userId and ignores userId in the frame', async () => {
      const store = {listFor: jest.fn().mockResolvedValue([])};
      const ws = {
        send: () => {},
        userId: 'real-user',
        readyState: 1,
      };

      // @ts-ignore
      const handle = createMessageHandler({}, store, {history: {enabled: true}});
      // @ts-ignore
      await handle(ws, {sessionId: 's1'}, {type: 'list_conversations', userId: 'evil-user'});

      expect(store.listFor).toHaveBeenCalledWith('real-user', expect.anything());
    });
  });

  describe('Store compatibility', () => {
    it('answers with UNSUPPORTED when store has no listFor', async () => {
      const store = {}; // no listFor
      const sent: any[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw)), readyState: 1};

      // @ts-ignore
      const handle = createMessageHandler({}, store, {history: {enabled: true}});
      // @ts-ignore
      await handle(ws, {sessionId: 's1'}, {type: 'list_conversations'});

      expect(sent).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
    });
  });

  describe('Concurrent handling', () => {
    it('answers list_conversations without waiting for the per-session lock', async () => {
      const store = {listFor: jest.fn().mockResolvedValue([])};
      const sent: any[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw)), readyState: 1};

      // A slow orchestrator that holds the lock
      let releaseLock = () => {};
      const lockRelease = new Promise<void>(resolve => {
        releaseLock = resolve;
      });
      const orchestrator = {
        processMessageStream: async function* () {
          await lockRelease;
          yield {type: 'text', text: 'hi'};
        },
      };

      // @ts-ignore
      const handle = createMessageHandler(orchestrator, store, {history: {enabled: true}});
      const session = {sessionId: 's1', userId: 'u1', entries: []};

      // Start a user_message which takes the lock
      // @ts-ignore
      const userMessagePromise = handle(ws, session, {type: 'user_message', content: 'hello'});

      // Send list_conversations while user_message is still running
      // @ts-ignore
      await handle(ws, session, {type: 'list_conversations'});

      // list_conversations should have been answered already
      expect(sent).toContainEqual(expect.objectContaining({type: 'conversation_list'}));

      // And it should be BEFORE stream_end of the user_message
      const streamEndIndex = sent.findIndex(m => m.type === 'stream_end');
      expect(streamEndIndex).toBe(-1);

      releaseLock();
      await userMessagePromise;

      expect(sent.findIndex(m => m.type === 'stream_end')).toBeGreaterThan(-1);
    });
  });
});

